param(
  [string]$ProjectRoot = "C:\Dev\chris"
)

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "CHRIS Central Dashboard System Repair" -ForegroundColor Green
Write-Host ""

$dashboardDir = Join-Path $ProjectRoot "src\components\dashboard"
$stylesDir = Join-Path $ProjectRoot "src\styles"
$cssPath = Join-Path $stylesDir "chris-dashboard.css"
$mainPath = Join-Path $ProjectRoot "src\main.jsx"

New-Item -ItemType Directory -Force -Path $dashboardDir | Out-Null
New-Item -ItemType Directory -Force -Path $stylesDir | Out-Null

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = Join-Path $ProjectRoot ".chris-backups\central-dashboard-repair-$stamp"
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null

if (Test-Path $dashboardDir) {
  Copy-Item $dashboardDir (Join-Path $backupDir "dashboard-before") -Recurse -Force
}
if (Test-Path $cssPath) {
  Copy-Item $cssPath (Join-Path $backupDir "chris-dashboard.css") -Force
}
if (Test-Path $mainPath) {
  Copy-Item $mainPath (Join-Path $backupDir "main.jsx") -Force
}

function Write-B64File {
  param([string]$Path,[string]$Value)
  [System.IO.File]::WriteAllBytes(
    $Path,
    [Convert]::FromBase64String($Value)
  )
}

Write-B64File (Join-Path $dashboardDir "DashboardCard.jsx") ""
Write-B64File (Join-Path $dashboardDir "AnalyticsPanel.jsx") ""
Write-B64File (Join-Path $dashboardDir "QuickActionCard.jsx") ""
Write-B64File (Join-Path $dashboardDir "RecentActivityList.jsx") ""
Write-B64File (Join-Path $dashboardDir "ModuleDashboardShell.jsx") ""
Write-B64File (Join-Path $dashboardDir "index.js") ""
Write-B64File $cssPath ""

if (-not (Test-Path $mainPath)) {
  throw "src\main.jsx not found."
}

$main = [System.IO.File]::ReadAllText($mainPath)

if ($main -notmatch 'chris-dashboard\.css') {
  $importLine = 'import "./styles/chris-dashboard.css";'
  $cssImports = [regex]::Matches(
    $main,
    '(?m)^import\s+["''][^"'']+\.css["''];\s*$'
  )

  if ($cssImports.Count -gt 0) {
    $last = $cssImports[$cssImports.Count - 1]
    $main = $main.Insert(
      $last.Index + $last.Length,
      "`r`n" + $importLine
    )
  }
  else {
    $main = $importLine + "`r`n" + $main
  }

  [System.IO.File]::WriteAllText(
    $mainPath,
    $main,
    [System.Text.UTF8Encoding]::new($false)
  )
}

Write-Host "Dashboard component files repaired." -ForegroundColor Green
Write-Host ""

Write-Host "=== INSTALLED COMPONENTS ===" -ForegroundColor Cyan
Get-ChildItem $dashboardDir |
  Select-Object Name,Length

Write-Host ""
Write-Host "=== REQUIRED FILE CHECK ===" -ForegroundColor Cyan

$required = @(
  "DashboardCard.jsx",
  "AnalyticsPanel.jsx",
  "QuickActionCard.jsx",
  "RecentActivityList.jsx",
  "ModuleDashboardShell.jsx",
  "index.js"
)

foreach ($file in $required) {
  $full = Join-Path $dashboardDir $file

  if (-not (Test-Path $full)) {
    throw "Still missing dashboard component: $file"
  }

  Write-Host "PASS: $file"
}

if (-not (Test-Path $cssPath)) {
  throw "Dashboard CSS is missing."
}
Write-Host "PASS: chris-dashboard.css"

Write-Host ""
Write-Host "=== BUILD ===" -ForegroundColor Cyan

Push-Location $ProjectRoot
try {
  npm run build
  if ($LASTEXITCODE -ne 0) {
    throw "Frontend build failed."
  }
}
finally {
  Pop-Location
}

Write-Host ""
Write-Host "============================================================"
Write-Host "CHRIS CENTRAL DASHBOARD SYSTEM REPAIR - PASSED" -ForegroundColor Green
Write-Host "============================================================"
Write-Host ""